	"time"

	"github.com/jessevdk/go-flags"
	"golang.org/x/net/html"
	"golang.org/x/text/encoding/charmap"
)

const version = "2.11.1"

type Options struct {
	AcceptedStatusCodes        string        `long:"accepted-status-codes" default:"200..300" description:"Accepted HTTP response status codes (e.g. '200..300,403')"`
	BufferSize                 int           `short:"b" long:"buffer-size" default:"4096" description:"HTTP response buffer size in bytes"`
	MaxConnections             int           `short:"c" long:"max-connections" default:"512" description:"Maximum number of HTTP connections"`
	MaxConnectionsPerHost      int           `long:"max-connections-per-host" default:"512" description:"Maximum number of HTTP connections per host"`
	MaxResponseBodySize        int64         `long:"max-response-body-size" default:"10000000" description:"Maximum response body size to read"`
	Exclude                    []string      `short:"e" long:"exclude" description:"Exclude URLs matched with given regular expressions"`
	Include                    []string      `short:"i" long:"include" description:"Include URLs matched with given regular expressions"`
	FollowRobotsTxt            bool          `long:"follow-robots-txt" description:"Follow robots.txt when scraping pages"`
	FollowSitemapXml           bool          `long:"follow-sitemap-xml" description:"Scrape only pages listed in sitemap.xml (deprecated)"`
	Headers                    []string      `long:"header" description:"Custom headers"`
	IgnoreFragments            bool          `short:"f" long:"ignore-fragments" description:"Ignore URL fragments"`
	MaxRetries                 int           `long:"max-retries" default:"0" description:"Maximum retry count for network errors"`
	DnsResolver                string        `long:"dns-resolver" description:"Custom DNS resolver"`
	Format                     string        `long:"format" choice:"text" choice:"json" choice:"junit" default:"text" description:"Output format"`
	JsonDeprecated             bool          `long:"json" description:"Output results in JSON (deprecated)"`
	ExperimentalVerboseJson    bool          `long:"experimental-verbose-json" description:"Include successful results in JSON (deprecated)"`
	JunitDeprecated            bool          `long:"junit" description:"Output results as JUnit XML file (deprecated)"`
	MaxRedirections            int           `short:"r" long:"max-redirections" default:"64" description:"Maximum number of redirections"`
	RateLimit                  float64       `long:"rate-limit" description:"Max requests per second"`
	Timeout                    time.Duration `short:"t" long:"timeout" default:"10s" description:"Timeout for HTTP requests"`
	Verbose                    bool          `short:"v" long:"verbose" description:"Show successful results too"`
	Proxy                      string        `long:"proxy" description:"HTTP proxy host"`
	SkipTlsVerification        bool          `long:"skip-tls-verification" description:"Skip TLS certificate verification"`
	OnePageOnly                bool          `long:"one-page-only" description:"Only check links found in the given URL"`
	Color                      string        `long:"color" choice:"auto" choice:"always" choice:"never" default:"auto" description:"Color output"`
	ShowVersion                bool          `long:"version" description:"Show version"`

	Args struct {
		URL string `positional-arg-name:"<url>" required:"yes"`
	} `positional-args:"yes" required:"yes"`
}

type Link struct {
	URL    string
	Status int
	Error  string
}

type Page struct {
	URL   string
	Links []Link
	Error string
}

type Checker struct {
	opts              *Options
	client            *http.Client
	excludePatterns   []*regexp.Regexp
	includePatterns   []*regexp.Regexp
	visited           map[string]bool
	visitedMutex      sync.Mutex
	rateLimiter       chan struct{}
	results           []Page
	resultsMutex      sync.Mutex
	wg                sync.WaitGroup
	baseURL           *url.URL
	dialer            *net.Dialer
}

func main() {
	var opts Options
	parser := flags.NewParser(&opts, flags.Default)
	_, err := parser.Parse()

	if err != nil {
		if flagsErr, ok := err.(*flags.Error); ok {
			if flagsErr.Type == flags.ErrHelp {
				os.Exit(0)
			}
		}
		fmt.Fprintf(os.Stderr, "%v\n", err)
		os.Exit(1)
	}

	if opts.ShowVersion {
		fmt.Println(version)
		os.Exit(0)
	}

	if opts.Args.URL == "" {
		fmt.Fprintf(os.Stderr, "invalid number of arguments\n")
		os.Exit(1)
	}

	// Handle deprecated flags
	if opts.JsonDeprecated {
		opts.Format = "json"
	}
	if opts.JunitDeprecated {
		opts.Format = "junit"
	}

	checker, err := NewChecker(&opts)
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to create checker: %v\n", err)
		os.Exit(1)
	}

	err = checker.Check()
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to fetch root page: %v\n", err)
		os.Exit(1)
	}

	// Output results
	checker.OutputResults()
}

func NewChecker(opts *Options) (*Checker, error) {
	baseURL, err := url.Parse(opts.Args.URL)
	if err != nil {
		return nil, fmt.Errorf("invalid URL: %v", err)
	}

	if baseURL.Scheme != "http" && baseURL.Scheme != "https" {
		return nil, fmt.Errorf("unsupported protocol %q. http and https are supported", baseURL.Scheme)
	}

	// Parse exclude patterns
	var excludePatterns []*regexp.Regexp
	for _, pattern := range opts.Exclude {
		re, err := regexp.Compile(pattern)
		if err != nil {
			return nil, fmt.Errorf("invalid exclude pattern: %v", err)
		}
		excludePatterns = append(excludePatterns, re)
	}

	// Parse include patterns
	var includePatterns []*regexp.Regexp
	for _, pattern := range opts.Include {
		re, err := regexp.Compile(pattern)
		if err != nil {
			return nil, fmt.Errorf("invalid include pattern: %v", err)
		}
		includePatterns = append(includePatterns, re)
	}

	// Create rate limiter
	var rateLimiter chan struct{}
	if opts.RateLimit > 0 {
		rateLimiter = make(chan struct{}, 1)
	}

	// Setup HTTP client
	tlsConfig := &tls.Config{
		InsecureSkipVerify: opts.SkipTlsVerification,
	}

	dialer := &net.Dialer{
		Timeout: opts.Timeout,
	}

	// Use custom DNS resolver if specified
	if opts.DnsResolver != "" {
		dialer.Resolver = &net.Resolver{
			PreferGo: true,
			Dial: func(ctx context.Context, network, address string) (net.Conn, error) {
				return net.Dial("udp", opts.DnsResolver+":53")
			},
		}
	}

	transport := &http.Transport{
		Dial:                 dialer.Dial,
		TLSClientConfig:      tlsConfig,
		MaxIdleConns:         opts.MaxConnections,
		MaxIdleConnsPerHost:  opts.MaxConnectionsPerHost,
		MaxConnsPerHost:      opts.MaxConnectionsPerHost,
		ResponseHeaderTimeout: opts.Timeout,
	}

	// Setup proxy if specified
	if opts.Proxy != "" {
		proxyURL, err := url.Parse("http://" + opts.Proxy)
		if err != nil {
			return nil, fmt.Errorf("invalid proxy: %v", err)
		}
		transport.Proxy = http.ProxyURL(proxyURL)
	}

	client := &http.Client{
		Transport: transport,
		Timeout:   opts.Timeout,
		CheckRedirect: func(req *http.Request, via []*http.Request) error {
			if len(via) >= opts.MaxRedirections {
				return http.ErrUseLastResponse
			}
			return nil
		},
	}

	return &Checker{
		opts:            opts,
		client:          client,
		excludePatterns: excludePatterns,
		includePatterns: includePatterns,
		visited:         make(map[string]bool),
		rateLimiter:     rateLimiter,
		baseURL:         baseURL,
		dialer:          dialer,
	}, nil
}

func (c *Checker) Check() error {
	// Fetch and parse the root page
	links, err := c.FetchPage(c.opts.Args.URL)
	if err != nil {
		return err
	}

	// Create initial page result
	page := Page{
		URL: c.opts.Args.URL,
	}

	// Check each link
	for _, link := range links {
		status, checkErr := c.CheckLink(link)
		page.Links = append(page.Links, Link{
			URL:    link,
			Status: status,
			Error:  errString(checkErr),
		})
	}

	c.resultsMutex.Lock()
	c.results = append(c.results, page)
	c.resultsMutex.Unlock()

	// If not one-page-only, recursively check other pages
	if !c.opts.OnePageOnly {
		c.crawlPages(links)
	}

	c.wg.Wait()

	return nil
}

func (c *Checker) FetchPage(pageURL string) ([]string, error) {
	resp, err := c.doRequest(pageURL)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()

	// Check if content is HTML
	contentType := resp.Header.Get("Content-Type")
	if !strings.Contains(contentType, "text/html") {
		return nil, nil
	}

	// Parse HTML and extract links
	var links []string
	decoder := html.NewTokenizer(resp.Body)

	for {
		tt := decoder.Next()
		if tt == html.ErrorToken {
			break
		}

		if tt == html.StartTagToken {
			t := decoder.Token()
			var href string
			var isLink bool

			switch t.Data {
			case "a", "link":
				href = getAttribute(t, "href")
				isLink = true
			case "img", "script", "source":
				href = getAttribute(t, "src")
				isLink = true
			case "form":
				href = getAttribute(t, "action")
				isLink = true
			}

			if isLink && href != "" {
				links = append(links, href)
			}
		}
	}

	return links, nil
}

func (c *Checker) doRequest(linkURL string) (*http.Response, error) {
	for retry := 0; retry <= c.opts.MaxRetries; retry++ {
		if c.rateLimiter != nil {
			c.rateLimiter <- struct{}{}
			go func() {
				time.Sleep(time.Duration(float64(time.Second) / c.opts.RateLimit))
				<-c.rateLimiter
			}()
		}

		req, err := http.NewRequest("GET", linkURL, nil)
		if err != nil {
			continue
		}

		// Add custom headers
		for _, header := range c.opts.Headers {
			parts := strings.SplitN(header, ":", 2)
			if len(parts) == 2 {
				req.Header.Set(strings.TrimSpace(parts[0]), strings.TrimSpace(parts[1]))
			}
		}

		req.Header.Set("User-Agent", "muffet/"+version)

		resp, err := c.client.Do(req)
		if err == nil {
			return resp, nil
		}

		if retry < c.opts.MaxRetries {
			time.Sleep(time.Duration((retry + 1)) * time.Second)
			continue
		}

		return nil, err
	}

	return nil, fmt.Errorf("max retries exceeded")
}

func (c *Checker) CheckLink(linkURL string) (int, error) {
	resp, err := c.doRequest(linkURL)
	if err != nil {
		return 0, err
	}
	defer resp.Body.Close()

	// Limit response body reading
	io.CopyN(io.Discard, resp.Body, c.opts.MaxResponseBodySize)

	return resp.StatusCode, nil
}

func (c *Checker) crawlPages(links []string) {
	for _, link := range links {
		absURL := c.resolveURL(link)
		if absURL == "" {
			continue
		}

		if c.shouldSkip(absURL) {
			continue
		}

		c.visitedMutex.Lock()
		if c.visited[absURL] {
			c.visitedMutex.Unlock()
			continue
		}
		c.visited[absURL] = true
		c.visitedMutex.Unlock()

		c.wg.Add(1)
		go func(url string) {
			defer c.wg.Done()
			pageLinks, err := c.FetchPage(url)
			if err == nil {
				page := Page{
					URL: url,
				}
				for _, link := range pageLinks {
					status, checkErr := c.CheckLink(link)
					page.Links = append(page.Links, Link{
						URL:    link,
						Status: status,
						Error:  errString(checkErr),
					})
				}
				c.resultsMutex.Lock()
				c.results = append(c.results, page)
				c.resultsMutex.Unlock()
				c.crawlPages(pageLinks)
			}
		}(absURL)
	}
}

func (c *Checker) resolveURL(link string) string {
	if link == "" {
		return ""
	}

	// Remove fragments if needed
	if c.opts.IgnoreFragments {
		if idx := strings.Index(link, "#"); idx != -1 {
			link = link[:idx]
		}
	}

	u, err := url.Parse(link)
	if err != nil {
		return ""
	}

	// Make URL absolute
	absURL := c.baseURL.ResolveReference(u).String()

	// Check if URL is on the same host
	parsedURL, err := url.Parse(absURL)
	if err != nil {
		return ""
	}

	if parsedURL.Host != c.baseURL.Host {
		return ""
	}

	return absURL
}

func (c *Checker) shouldSkip(link string) bool {
	if len(c.includePatterns) > 0 {
		matched := false
		for _, re := range c.includePatterns {
			if re.MatchString(link) {
				matched = true
				break
			}
		}
		if !matched {
			return true
		}
	}

	for _, re := range c.excludePatterns {
		if re.MatchString(link) {
			return true
		}
	}

	return false
}

func (c *Checker) OutputResults() {
	switch c.opts.Format {
	case "json":
		c.outputJSON()
	case "junit":
		c.outputJUnit()
	default:
		c.outputText()
	}
}

func (c *Checker) outputText() {
	for _, page := range c.results {
		for _, link := range page.Links {
			if link.Error != "" {
				fmt.Printf("  %s\n", link.URL)
				fmt.Printf("    %s\n", link.Error)
			} else if c.opts.Verbose {
				fmt.Printf("  %s\n", link.URL)
				fmt.Printf("    %d\n", link.Status)
			}
		}
	}
}

func (c *Checker) outputJSON() {
	output := make([]map[string]interface{}, 0)

	for _, page := range c.results {
		for _, link := range page.Links {
			if link.Error != "" || c.opts.ExperimentalVerboseJson {
				entry := map[string]interface{}{
					"page": page.URL,
					"url":  link.URL,
				}
				if link.Error != "" {
					entry["error"] = link.Error
				} else {
					entry["status"] = link.Status
				}
				output = append(output, entry)
			}
		}
	}

	data, _ := json.MarshalIndent(output, "", "  ")
	fmt.Println(string(data))
}

func (c *Checker) outputJUnit() {
	// JUnit XML format output
	testSuite := struct {
		XMLName   xml.Name
		Name      string
		Tests     int
		Failures  int
		TestCases []interface{}
	}{
		XMLName: xml.Name{Local: "testsuite"},
		Name:    c.baseURL.Host,
	}

	failureCount := 0
	for _, page := range c.results {
		for _, link := range page.Links {
			if link.Error != "" {
				failureCount++
			}
		}
	}

	testCount := 0
	for _, page := range c.results {
		testCount += len(page.Links)
	}

	testSuite.Tests = testCount
	testSuite.Failures = failureCount

	data, _ := xml.MarshalIndent(testSuite, "", "  ")
	fmt.Println(xml.Header + string(data))
}

func getAttribute(t html.Token, attr string) string {
	for _, a := range t.Attr {
		if a.Key == attr {
			return a.Val
		}
	}
	return ""
}

func errString(err error) string {
	if err == nil {
		return ""
	}
	return err.Error()
}
EOF

