				val = strings.TrimPrefix(arg, "--timeout=")
			}
			timeout, _ := time.ParseDuration(val)
			opts.Timeout = timeout
			i++
			continue
		}

		if arg == "-t" || arg == "--timeout" {
			i++
			if i < len(args) {
				timeout, _ := time.ParseDuration(args[i])
				opts.Timeout = timeout
				i++
			}
			continue
		}

		if strings.HasPrefix(arg, "--proxy=") {
			val := strings.TrimPrefix(arg, "--proxy=")
			opts.Proxy = val
			i++
			continue
		}

		if arg == "--proxy" {
			i++
			if i < len(args) {
				opts.Proxy = args[i]
				i++
			}
			continue
		}

		if strings.HasPrefix(arg, "--color=") {
			val := strings.TrimPrefix(arg, "--color=")
			opts.Color = val
			i++
			continue
		}

		if arg == "--color" {
			i++
			if i < len(args) {
				opts.Color = args[i]
				i++
			}
			continue
		}

		if strings.HasPrefix(arg, "--accepted-status-codes=") {
			val := strings.TrimPrefix(arg, "--accepted-status-codes=")
			opts.AcceptedStatusCodes = val
			i++
			continue
		}

		if arg == "--accepted-status-codes" {
			i++
			if i < len(args) {
				opts.AcceptedStatusCodes = args[i]
				i++
			}
			continue
		}

		// Positional argument
		if !strings.HasPrefix(arg, "-") {
			opts.URL = arg
			i++
			continue
		}

		// Unknown flag
		if strings.HasPrefix(arg, "--") {
			fmt.Fprintf(os.Stderr, "unknown flag `%s'\n", strings.TrimPrefix(arg, "--"))
			os.Exit(1)
		}

		if strings.HasPrefix(arg, "-") {
			fmt.Fprintf(os.Stderr, "unknown flag `%s'\n", strings.TrimPrefix(arg, "-"))
			os.Exit(1)
		}

		i++
	}

	if opts.ShowVersion {
		fmt.Println(version)
		os.Exit(0)
	}

	if opts.Timeout == 0 {
		opts.Timeout = 10 * time.Second
	}

	if opts.URL == "" {
		fmt.Fprintf(os.Stderr, "invalid number of arguments\n")
		os.Exit(1)
	}

	// Handle deprecated flags
	if opts.JsonDeprecated {
		opts.Format = "json"
	}
	if opts.JunitDeprecated {
		opts.Format = "junit"
	}

	checker, err := NewChecker(opts)
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to create checker: %v\n", err)
		os.Exit(1)
	}

	err = checker.Check()
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to fetch root page: %v\n", err)
		os.Exit(1)
	}

	// Output results
	checker.OutputResults()
}

