func NewChecker(opts *Options) (*Checker, error) {
	baseURL, err := url.Parse(opts.URL)
	if err != nil {
		return nil, fmt.Errorf("invalid URL: %v", err)
	}

	if baseURL.Scheme != "http" && baseURL.Scheme != "https" {
		return nil, fmt.Errorf("unsupported protocol %q. http and https are supported", baseURL.Scheme)
	}

	// Parse exclude patterns
	var excludePatterns []*regexp.Regexp
	for _, pattern := range opts.Exclude {
		re, err := regexp.Compile(pattern)
		if err != nil {
			return nil, fmt.Errorf("invalid exclude pattern: %v", err)
		}
		excludePatterns = append(excludePatterns, re)
	}

	// Parse include patterns
	var includePatterns []*regexp.Regexp
	for _, pattern := range opts.Include {
		re, err := regexp.Compile(pattern)
		if err != nil {
			return nil, fmt.Errorf("invalid include pattern: %v", err)
		}
		includePatterns = append(includePatterns, re)
	}

	// Create rate limiter
	var rateLimiter chan struct{}
	if opts.RateLimit > 0 {
		rateLimiter = make(chan struct{}, 1)
	}

	// Setup HTTP client
	tlsConfig := &tls.Config{
		InsecureSkipVerify: opts.SkipTlsVerification,
	}

	dialer := &net.Dialer{
		Timeout: opts.Timeout,
	}

	// Use custom DNS resolver if specified
	if opts.DnsResolver != "" {
		dialer.Resolver = &net.Resolver{
			PreferGo: true,
			Dial: func(ctx context.Context, network, address string) (net.Conn, error) {
				return net.Dial("udp", opts.DnsResolver+":53")
			},
		}
	}

	transport := &http.Transport{
		Dial:                      dialer.Dial,
		TLSClientConfig:           tlsConfig,
		MaxIdleConns:              opts.MaxConnections,
		MaxIdleConnsPerHost:       opts.MaxConnectionsPerHost,
		MaxConnsPerHost:           opts.MaxConnectionsPerHost,
		ResponseHeaderTimeout:     opts.Timeout,
		DisableKeepAlives:         false,
		DisableCompression:        false,
		MaxResponseHeaderBytes:    int64(opts.BufferSize),
	}

	// Setup proxy if specified
	if opts.Proxy != "" {
		proxyURL, err := url.Parse("http://" + opts.Proxy)
		if err != nil {
			return nil, fmt.Errorf("invalid proxy: %v", err)
		}
		transport.Proxy = http.ProxyURL(proxyURL)
	}

	client := &http.Client{
		Transport: transport,
		Timeout:   opts.Timeout,
		CheckRedirect: func(req *http.Request, via []*http.Request) error {
			if len(via) >= opts.MaxRedirections {
				return http.ErrUseLastResponse
			}
			return nil
		},
	}

	return &Checker{
		opts:            opts,
		client:          client,
		excludePatterns: excludePatterns,
		includePatterns: includePatterns,
		visited:         make(map[string]bool),
		rateLimiter:     rateLimiter,
		baseURL:         baseURL,
	}, nil
}

func (c *Checker) Check() error {
	// Fetch and parse the root page
	links, err := c.FetchPage(c.opts.URL)
	if err != nil {
		return err
	}

	// Create initial page result
	page := Page{
		URL: c.opts.URL,
	}

	// Check each link
	for _, link := range links {
		status, checkErr := c.CheckLink(link)
		page.Links = append(page.Links, Link{
			URL:    link,
			Status: status,
			Error:  errString(checkErr),
		})
	}

	c.resultsMutex.Lock()
	c.results = append(c.results, page)
	c.resultsMutex.Unlock()

	// If not one-page-only, recursively check other pages
	if !c.opts.OnePageOnly {
		c.crawlPages(links)
	}

	c.wg.Wait()

	return nil
}

func (c *Checker) FetchPage(pageURL string) ([]string, error) {
	resp, err := c.doRequest(pageURL)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()

	// Check if content is HTML
	contentType := resp.Header.Get("Content-Type")
	if !strings.Contains(contentType, "text/html") {
		return nil, nil
	}

	// Parse HTML and extract links
	var links []string
	decoder := html.NewTokenizer(resp.Body)

	for {
		tt := decoder.Next()
		if tt == html.ErrorToken {
			break
		}

		if tt == html.StartTagToken {
			t := decoder.Token()
			var href string
			var isLink bool

			switch t.Data {
			case "a", "link":
				href = getAttribute(t, "href")
				isLink = true
			case "img", "script", "source":
				href = getAttribute(t, "src")
				isLink = true
			case "form":
				href = getAttribute(t, "action")
				isLink = true
			}

			if isLink && href != "" {
				links = append(links, href)
			}
		}
	}

	return links, nil
}

func (c *Checker) doRequest(linkURL string) (*http.Response, error) {
	for retry := 0; retry <= c.opts.MaxRetries; retry++ {
		if c.rateLimiter != nil {
			c.rateLimiter <- struct{}{}
			go func() {
				time.Sleep(time.Duration(float64(time.Second) / c.opts.RateLimit))
				<-c.rateLimiter
			}()
		}

		req, err := http.NewRequest("GET", linkURL, nil)
		if err != nil {
			continue
		}

		// Add custom headers
		for _, header := range c.opts.Headers {
			parts := strings.SplitN(header, ":", 2)
			if len(parts) == 2 {
				req.Header.Set(strings.TrimSpace(parts[0]), strings.TrimSpace(parts[1]))
			}
		}

		req.Header.Set("User-Agent", "muffet/"+version)

		resp, err := c.client.Do(req)
		if err == nil {
			return resp, nil
		}

		if retry < c.opts.MaxRetries {
			time.Sleep(time.Duration((retry + 1)) * time.Second)
			continue
		}

		return nil, err
	}

	return nil, fmt.Errorf("max retries exceeded")
}

func (c *Checker) CheckLink(linkURL string) (int, error) {
	resp, err := c.doRequest(linkURL)
	if err != nil {
		return 0, err
	}
	defer resp.Body.Close()

	// Limit response body reading
	io.CopyN(io.Discard, resp.Body, c.opts.MaxResponseBodySize)

	return resp.StatusCode, nil
}

func (c *Checker) crawlPages(links []string) {
	for _, link := range links {
		absURL := c.resolveURL(link)
		if absURL == "" {
			continue
		}

		if c.shouldSkip(absURL) {
			continue
		}

		c.visitedMutex.Lock()
		if c.visited[absURL] {
			c.visitedMutex.Unlock()
			continue
		}
		c.visited[absURL] = true
		c.visitedMutex.Unlock()

		c.wg.Add(1)
		go func(url string) {
			defer c.wg.Done()
			pageLinks, err := c.FetchPage(url)
			if err == nil && pageLinks != nil {
				page := Page{
					URL: url,
				}
				for _, link := range pageLinks {
					status, checkErr := c.CheckLink(link)
					page.Links = append(page.Links, Link{
						URL:    link,
						Status: status,
						Error:  errString(checkErr),
					})
				}
				c.resultsMutex.Lock()
				c.results = append(c.results, page)
				c.resultsMutex.Unlock()
				c.crawlPages(pageLinks)
			}
		}(absURL)
	}
}

func (c *Checker) resolveURL(link string) string {
	if link == "" {
		return ""
	}

	// Remove fragments if needed
	if c.opts.IgnoreFragments {
		if idx := strings.Index(link, "#"); idx != -1 {
			link = link[:idx]
		}
	}

	u, err := url.Parse(link)
	if err != nil {
		return ""
	}

	// Make URL absolute
	absURL := c.baseURL.ResolveReference(u).String()

	// Check if URL is on the same host
	parsedURL, err := url.Parse(absURL)
	if err != nil {
		return ""
	}

	if parsedURL.Host != c.baseURL.Host {
		return ""
	}

	return absURL
}

func (c *Checker) shouldSkip(link string) bool {
	if len(c.includePatterns) > 0 {
		matched := false
		for _, re := range c.includePatterns {
			if re.MatchString(link) {
				matched = true
				break
			}
		}
		if !matched {
			return true
		}
	}

	for _, re := range c.excludePatterns {
		if re.MatchString(link) {
			return true
		}
	}

	return false
}

func (c *Checker) OutputResults() {
	switch c.opts.Format {
	case "json":
		c.outputJSON()
	case "junit":
		c.outputJUnit()
	default:
		c.outputText()
	}
}

func (c *Checker) outputText() {
	for _, page := range c.results {
		for _, link := range page.Links {
			if link.Error != "" {
				fmt.Printf("  %s\n", link.URL)
				fmt.Printf("    %s\n", link.Error)
			} else if c.opts.Verbose {
				fmt.Printf("  %s\n", link.URL)
				fmt.Printf("    %d\n", link.Status)
			}
		}
	}
}

func (c *Checker) outputJSON() {
	output := make([]map[string]interface{}, 0)

	for _, page := range c.results {
		for _, link := range page.Links {
			if link.Error != "" || c.opts.ExperimentalVerboseJson {
				entry := map[string]interface{}{
					"page": page.URL,
					"url":  link.URL,
				}
				if link.Error != "" {
					entry["error"] = link.Error
				} else {
					entry["status"] = link.Status
				}
				output = append(output, entry)
			}
		}
	}

	data, _ := json.MarshalIndent(output, "", "  ")
	fmt.Println(string(data))
}

func (c *Checker) outputJUnit() {
	// JUnit XML format output
	testSuite := struct {
		XMLName   xml.Name
		Name      string
		Tests     int
		Failures  int
		TestCases []interface{}
	}{
		XMLName: xml.Name{Local: "testsuite"},
		Name:    c.baseURL.Host,
	}

	failureCount := 0
	for _, page := range c.results {
		for _, link := range page.Links {
			if link.Error != "" {
				failureCount++
			}
		}
	}

	testCount := 0
	for _, page := range c.results {
		testCount += len(page.Links)
	}

	testSuite.Tests = testCount
	testSuite.Failures = failureCount

	data, _ := xml.MarshalIndent(testSuite, "", "  ")
	fmt.Println(xml.Header + string(data))
}

func getAttribute(t html.Token, attr string) string {
	for _, a := range t.Attr {
		if a.Key == attr {
			return a.Val
		}
	}
	return ""
}

func errString(err error) string {
	if err == nil {
		return ""
	}
	return err.Error()
}
